SELECT 


    AND s.museum_id = #{museumId}
    AND s.exhibition_id = #{exhibitionId}
    AND s.visit_date = #{date}
    AND s.visit_date >= #{fromDate}
    AND s.status = #{status}
    AND s.visit_date >= CURDATE()

ORDER BY s.visit_date ASC, s.start_time ASC

